qualified_questions.sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT (COUNT(DISTINCT ?lengthUnit) AS ?numberOfLengthUnits)
WHERE {
  ?lengthUnit rdf:type s4envi:LengthUnit .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX s4envi: <http://example.org/s4envi#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT (COUNT(?unit) AS ?count)
WHERE {
  ?unit rdf:type s4envi:FrequencyUnit ;
        rdf:type owl:NamedIndividual .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?unit
WHERE {
  ?unit rdf:type owl:NamedIndividual .
  FILTER NOT EXISTS { ?unit rdf:type s4envi:LengthUnit }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX saref: <https://saref.etsi.org/core/>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?measurementType ?superClass
WHERE {
  ?measurementType rdfs:subClassOf saref:Measurement .
  OPTIONAL { ?measurementType rdfs:subClassOf ?superClass . }
}

PREFIX s4envi: <http://example.org/s4envi#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (COUNT(?device) AS ?numberOfDevices)
WHERE {
  ?particularDevice s4envi:isConnectedTo ?device .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT (COUNT(DISTINCT ?group) AS ?distinctGroups)
WHERE {
  {
    SELECT ?device (GROUP_CONCAT(?connectedDevice; separator=",") AS ?group)
    WHERE {
      ?device s4envi:isConnectedTo ?connectedDevice .
    }
    GROUP BY ?device
  }
  BIND(COALESCE(?group, STR(?device)) AS ?group)
}
GROUP BY ?group

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX s4envi: <http://example.org/s4envi#>

SELECT ?property
WHERE {
  ?property rdf:type owl:ObjectProperty ;
            rdf:type owl:SymmetricProperty .
}

PREFIX saref: <https://saref.etsi.org/core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  saref:Device rdfs:isDefinedBy ?definition
}
